import threading
class BalanceTracker_12:
    def __init__(self):
        self.balance = 1000
        self.lock = threading.Lock()
    def withdraw(self, amount):
        # Fixed: Thread-safe critical section under mutex
        with self.lock:
            if self.balance >= amount:
                self.balance -= amount
                return True
            return False

